import{_ as o,a as r}from"./chunks/d7dfe06a77a8a24f2bc8.BMxwDGkh.js";import{_ as a,C as n,o as s,c as l,j as t,a as i,E as h,a5 as g}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"如何攻克你的重大目标，并在2-3个月内实现它们","description":"","frontmatter":{"title":"如何攻克你的重大目标，并在2-3个月内实现它们","originalTitle":"How To Attack Your Big Goals & Achieve Them In 2-3 Months","date":"2025-02-22","originalUrl":"https://thedankoe.com/letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months/","minutes":18,"sourceHash":"ae9bf31910b6bd632f170f1b59718486c21ca5496c9ee010dd40cc1d76c32bea","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months/"}]]},"headers":[],"relativePath":"letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months.md","filePath":"letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months.md"}'),c={name:"letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months.md"};function d(u,p,m,b,f,k){const e=n("ArticleMeta");return s(),l("div",null,[p[0]||(p[0]=t("h1",{id:"如何攻克你的重大目标-并在2-3个月内实现它们",tabindex:"-1"},[i("如何攻克你的重大目标，并在2-3个月内实现它们 "),t("a",{class:"header-anchor",href:"#如何攻克你的重大目标-并在2-3个月内实现它们","aria-label":'Permalink to "如何攻克你的重大目标，并在2-3个月内实现它们"'},"​")],-1)),h(e),p[1]||(p[1]=g('<p><a href="https://www.youtube.com/embed/n0AB6pZpotg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>第四期写作特训营（Writer&#39;s Bootcamp）将于3月4日开始。</p><p>而且……我们还会免费加送一场额外的通话。</p><p>Kortex AI v1版本将在接下来一周内准备好发布。这意味着在特训营结束前，会加入更多AI功能，我们会讲解创意生成、推文、推文串、newsletter，以及用AI进行编辑的课程和提示词（prompts）。这部分内容本应单独收费，但你会作为附赠内容获得它。</p><p>如果你想要：</p><ul><li>基于你的个人兴趣，创建属于你自己的细分领域</li><li>将1个想法转化为7天的内容（帖子、推文串、newsletter）</li><li>把这些内容再利用到所有平台（包括YouTube）</li><li>用模板来组织你的写作，避免“不知道”该从何下手</li><li>获得一套课程体系，并终身免费更新，因为我们会持续把它做得比现在更好</li></ul><p>内容很多。是一场完整的受众打造大师课。所以要为接下来紧张的5周（加上AI内容部分就是6周）做好准备。</p><p><a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">在3月4日前报名。</a></p><p>–––</p><p>我时不时会剃光头。</p><p>一开始，是因为害怕变秃。</p><p>我剃掉头发，是想把那层“金发”的隐喻性绷带一次撕下来，好让自己习惯我“注定”要有的模样。</p><p>我也相信，太多男人把自信寄托在头发上，但这不是重点。</p><p>结果发现，我根本没有变秃，我的发际线一直看起来就像iPhone的顶部形状（正如Kortex的工程师Ian非常“贴心”地给我画出来的那样），我只是太在意它了。</p><p><img src="'+o+'" alt=""></p><p>现在，我知道这听起来可能有点老套，但剃头这件事，已经成为我转换到“另一个自我”的象征。一种能让我快速实现目标、保持纯粹专注的次级身份，像一名即将奔赴战场的战士。</p><p>一种让自己变得如此脆弱，以至于我别无选择、只能接受它的方式。当事情必须完成时，这就是一种强制专注的机制。说实话，这正逐渐成为我最喜欢的造型（有些日子是这样。有些日子则不太行。）</p><p>事实上，这正是科比·布莱恩特（Kobe Bryant）的秘密武器。他的另一个自我“黑曼巴”（The Black Mamba），是他在人生某个艰难阶段所采用的形象。它反映了他想在篮球场上体现出的那种心态。</p><p>我们很快就会深入探讨这背后的心理学原理。</p><p>在我自己的生活中，我常常在“战士”和“僧侣”这两种原型之间来回切换。</p><p>战斗模式（war mode）和僧侣模式（monk mode）。</p><p>很多人都熟悉“僧侣模式”。它已经成为一种自我提升的策略：你从世界中消失、去除干扰，并践行某种禁欲主义，在追求个人成长的过程中拒绝世俗的享乐。</p><p>“战斗模式”正好相反。</p><p>你去攻克你的目标。你模拟一场狩猎。你对一切说“好”。你让自己暴露在大量的经历之中。你用混乱来冲击自己的心智，逼迫自己扩展成一个全新的身份。<strong>你成为那个能扛得起巨大责任重担的人。</strong>一个在压力下不会崩溃的人，因为崩溃就意味着死亡。</p><p>我用“战斗模式”作为一种手段，把我的身心和事业推向下一个层次，效果好得惊人。</p><p>现代生活的问题在于，它太舒适了。</p><p>人们整天做着自己厌恶的简单任务，从不在创造层面挑战自己，却觉得自己需要从工作中“休息一下”。</p><p>就我个人而言，我认为大多数人需要的其实是<strong>更多的工作</strong>，而不是<strong>更多的休息</strong>。</p><p>第一，因为对大多数人来说，所谓的“休息”其实等同于从无聊中逃向享乐，而不是从高强度、令人兴奋的工作中进行深度恢复。</p><p>第二，因为普通人普遍缺乏那种为一个有意义的目标全力以赴、纯粹专注的强度期。</p><p>他们缺少真正的平衡：<strong>对比反差</strong>。</p><p>有意义的工作和有意义的休息。</p><p>两者都要以纯粹的专注去完成。</p><p>在宏观（数年）、中观（数月）和微观（数日）层面都是如此。</p><p>不是走中间路线，而是走一条高峰迭起、低谷频现的路。</p><p>惨烈的失败和极致的成功。</p><p>最深刻的教训正是从这些经历中学到的，而如果你一直漂浮在中间地带，生活就会变成一片无聊与焦虑交织的模糊。</p><p>太多人只是想逃离日常生活的压力和平淡无奇，于是他们以为多休息一点，或来一次豪华假期就能解决问题。</p><p>我想提出另一种解决方案。</p><p>稍微“疯”一点。</p><p>一夜之间切换开关。</p><p>彻底变成一个全新的人。</p><p>我们来学学该怎么做。</p><h2 id="另一个自我-效应——踏入一个新身份" tabindex="-1">“另一个自我”效应——踏入一个新身份 <a class="header-anchor" href="#另一个自我-效应——踏入一个新身份" aria-label="Permalink to &quot;“另一个自我”效应——踏入一个新身份&quot;">​</a></h2><blockquote><p>另一个自我，是你现在的样子与你本该成为的样子之间的一座桥梁……它让你能够跳出自身，看到更大的全局。</p><p>——Todd Herman，《The Alter Ego Effect》</p></blockquote><p>我在高中英语课上写过一篇论文。</p><p>我不记得为什么要写这篇论文，但我记得自己写了什么。</p><p>简而言之，我写的是——<strong>我在不同人面前并不是同一个人</strong>。</p><p>在课堂上、在教堂（被迫去的时候）、和朋友在一起、和父母在一起，以及在网上和人聊天时——通常是在打《使命召唤》（Call of Duty）、《光环3》（Halo 3）或《英雄联盟》（League Of Legends）时——我都是不同的人。</p><p>如果我用对付那个在“搜索与摧毁”开局30秒内就在地图另一端一枪爆头我的蠢小子的口气跟我父母说话，他们大概会跟我断绝关系，我为什么要那样跟他们说话呢？</p><p>让我惊讶的是，我的老师，Wright先生，竟然<strong>认同我</strong>。</p><p>他把我叫到一边，说他自己也是这样，只是不太愿意谈这个，因为这可能会让他显得不够真诚、两面三刀。这里是我转述他的话。</p><p>事实是，人类都是变形者。</p><p>我们是创造者。是多面手（generalists）。我们为了生存和繁荣而不断适应各种情境。</p><p>我们的心智拥有一种独特的能力，可以转换视角——从而改变注意力所投向的“风景”——但很少有人真正练习过这项技能。</p><p>你其实每天都在这么做。你会调动自己身份中不同的特质，去在不同情境中发挥最佳表现。但当你学会掌控这种能力后，你就能做到看似不可能的事情。</p><p>这正是为什么这么多人在自律和自信上苦苦挣扎。</p><p>他们被困在一片被自我怀疑和不安笼罩的心智之中。</p><p>他们无法<strong>跳出</strong>那个小盒子，从一个全新的角度去看待事情。</p><p>于是他们就此沉沦。</p><p>他们的目标、梦想和野心，被放在书架上，慢慢积灰。</p><p>你想创办的那个企业。你想拥有的那种社交生活。你想塑造的那个身体和心智。当你过着自己并不想要的生活时，这些东西不断在你脑中萦绕、纠缠，让你心中的混乱愈演愈烈。</p><p>于是，“另一个自我”登场了。</p><p>这个概念由Todd Herman提出，他是《The Alter Ego Effect》一书的作者。</p><p>马丁·路德·金（Martin Luther King Jr）会在演讲时戴上没有度数的眼镜，把自己塑造成一位“杰出的知识分子”。</p><p>科比·布莱恩特会变身成“黑曼巴”，因为黑曼巴蛇迅猛、流畅，又令人胆寒。</p><p>与此类似，像Eddie Hall这样的大力士选手，会想象自己的孩子被他正在举起的重物压碎。他说，凭常理来看，他绝对不可能举起那种破纪录的重量，没有任何人能做到。但当他<strong>真的</strong>相信自己正处于生死关头时，他就能激发出一种超乎常人的力量。</p><p>为什么这有效？</p><p>当你采用一个“另一个自我”时，你的心智会开始聚焦在“你应该如何表现”上。你有限的心智能量——大约每秒50比特的有意识信息处理量——会被这种注意力的转移所消耗。<strong>你根本没有多余的带宽，去把能量分给自我怀疑和不安全感。</strong></p><p>关键点在于：你所能给予的注意力是有限的。而当你把它全部给了怀疑与不安，那便成了你的整个世界。你会变成你所专注的东西，但要扩展进入一个允许注意力转移的全新心智状态，是需要努力的。</p><p>所以，我们需要：</p><ul><li>建立一个心理框架，把注意力从自我怀疑和恐惧上转移开</li><li>打造一个新的身份，并通过重复练习和学习不断扩展进这个身份中</li><li>制定一个计划，让我们的注意力进一步收窄，从而进入心流状态</li></ul><p>给这个过程足够的时间，你的生活会以无数种方式发生改变。</p><p>下面，正是当你需要发挥表现时，如何打造一个可以随时切换进入的“另一个自我”的具体方法：</p><h3 id="_1-愿景——你想要什么" tabindex="-1">1）愿景——你想要什么？ <a class="header-anchor" href="#_1-愿景——你想要什么" aria-label="Permalink to &quot;1）愿景——你想要什么？&quot;">​</a></h3><p>首先，我们需要一个<strong>注意力锚点</strong>。</p><p>我们需要某种东西，把你的注意力从怀疑和不安全感上拉走。</p><p>你需要一座由<strong>你自己</strong>建造的坚固心智之屋，而不是别人替你建的。一座你可以在外界条件变得严酷时，用来装饰、居住的房子。</p><p>这不能是随便一个目标，也不能是因为别人在做、或者你感受到一点点动力，就随口定下的新年愿望。它必须有<strong>引力</strong>。它必须有意义。它必须是你愿意为之奉献一生的东西。</p><p>但这一切都不会一蹴而就。</p><p>你的愿景，就像做其他任何事一样，需要从头开始。</p><p>一开始它会很糟糕，感觉很不真实。但你需要先把东西写在纸上，这样你才有东西可以去改进。</p><p>随着你不断取得进展，你会发现有些你以为自己想要的东西，其实已经不再想要了。于是你不断<strong>迭代</strong>。你在你的愿景上添上一笔又一笔。这个过程永不停止。它是一幅你不断添加笔触的画。</p><p>你可以从我用的这个模板开始，<a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">简明人生规划表（免费）</a>，或者直接把这些问题写在纸上，或写进你<a href="https://kortex.co/" target="_blank" rel="noreferrer">最喜欢的笔记应用。</a></p><ul><li>你想以怎样的形象出现、说话方式如何、别人会如何看待你？为什么？</li><li>你想生活在什么样的环境中？为什么？</li><li>你想对他人产生怎样的影响？为什么？</li><li>如果金钱是你所产生影响的映射，那你想赚多少钱？</li><li>你能想象自己在哪方面真正做得非常出色、并因此而被人所知？为什么？</li><li>你希望自己一天的日常生活，具体到细节，是什么样子？为什么？</li></ul><p>这只是一个起点。</p><p>记住，随着你不断取得进展，你会不断增添、删减、打磨它。</p><p>但如果你根本没有动力去开始呢？</p><p>如果你甚至连动起来都很吃力呢？</p><h3 id="_2-清晰度——你如何取得进展" tabindex="-1">2）清晰度——你如何取得进展？ <a class="header-anchor" href="#_2-清晰度——你如何取得进展" aria-label="Permalink to &quot;2）清晰度——你如何取得进展？&quot;">​</a></h3><p>缺乏自信是很残酷的一件事。</p><p>你不停地质疑自己的行动，也找不到任何可持续的动力来源，因为它总是被怀疑所笼罩。</p><p>事实是，缺乏自信归根结底源自缺乏清晰度。</p><p>清晰度这个等式的前半部分，取决于视角（perspective）。我们已经通过一个能借由信念不断增强的愿景，解决了这一半问题。清晰度的后半部分，则在于<strong>知道该专注在什么上</strong>。</p><p>幸运的是，这不是靠运气解决的问题。</p><p>这是一个策略问题。</p><p>换句话说，你需要一个计划。</p><p>你的愿景可能看起来遥不可及，就像一颗北极星。</p><p>而一个计划，就是一种猜测——一开始很笨拙，之后逐渐变得有依据——它能让你的注意力更聚焦在，哪些步骤真正能推动全局向前。</p><blockquote><p>因为最佳体验取决于一个人能否逐时逐刻地掌控自己意识中发生的一切，所以每个人都必须依靠自身的努力和创造力去实现它。</p><p>——米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>当你的注意力聚焦在一项任务上时，分心的事就更难进入意识。但如果你不知道接下来该做什么，再接下来又该做什么……一切就开始崩塌。如果下一个任务很难，你就会焦虑。如果它太简单，你就会感到无聊。就在那一刻，你的注意力从你的愿景中分裂出去，混乱开始渗入。</p><p>让我们制定一个计划。</p><p><strong>第一</strong>，把你的愿景拆解成容易消化的里程碑。</p><p>如果我想每年赚100万美元，那么里程碑可以是先赚到第一个1美元，然后是10,000美元，然后是100,000美元，以此类推。你不太可能不先赚到第一个1万美元就直接跳到100万美元。而要达到1万美元你必须做的事，会和达到100万美元所需做的事大不相同。</p><p><strong>第二</strong>，写下你要达成第一个里程碑具体需要做什么。</p><p>就这个例子而言，为了赚到我的第一美元，我显然需要创业。具体来说，是一个与我整体愿景和兴趣相符的事业。所以在我的情况下，这涉及写作。</p><p>现在我至少有了一些清晰度。我可以开始学习其他作家作为<strong>新手</strong>时是怎么起步的。</p><p><strong>第三</strong>，写下你为了做那件事必须学习的东西。</p><p>要开始一项写作事业，我需要学习市场营销、销售、内容创作，以及如何打造一款产品或服务。</p><p>如果我专注于第一个1美元的里程碑，我可以做一本电子书，定价10美元，然后在我通过内容创作积累起来的小规模受众中，在社交媒体上推广它。</p><p>提醒一下，<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">作家训练营（The Writer&#39;s Bootcamp）</a>（现在加入了YouTube和AI内容）将于3月4日开课，如果你想围绕自己的兴趣打造受众，可以关注。</p><p><strong>第四</strong>，列出真正能带来结果的每日任务。而不只是忙碌的杂事。</p><p>对于写作事业而言，这意味着发布高质量的内容。就像自出版科幻小说作家 Devon Eriksen 那样。</p><p>我见过其他作者抱怨社交媒体不是好的销售渠道，但你看看他们的主页，他们只是在发自己书的链接。你他妈的怎么指望靠这个建立受众？他们对你书里的想法一无所知，凭什么要在乎你的书？</p><p>你需要发表你的信念、观点，教人们了解你感兴趣的事情。他们一开始并不关心你的书。他们首先关心的是你。然后他们因为喜欢你，才会购买你的书（或其他任何产品）。</p><p>你可以，也应该，把你的计划细化到尽可能具体的程度。</p><p>但就像你的愿景一样，这只是一个初次迭代，你会随着时间不断补充完善。</p><p>这就是为什么大多数人无法坚持到底。</p><p>他们卡在诸如“我不知道该开什么样的生意”这样的问题上，而不是随便先开始<strong>任何一个</strong>——因为构成一个生意的技能，其实能相当好地迁移到你之后转型的任何其他生意上。这不仅适用于商业。</p><p>从哪里开始并不重要。你很可能会像其他所有人一样改变方向。重要的是你通过开始去学到了什么，这样你才能继续前进。</p><p>如果你还不知道该做什么，没关系。</p><p>如果你感到不知所措，没关系。</p><p>你正在改变你的人生。</p><p>这当然会让你感觉像是在大海中央游泳。</p><p>期望答案会自动“找上门来”，这是父母和老师从小告诉你该做什么留下的一种残余社会条件反射……看看那把你带到了哪里。</p><p>这正是我们接下来需要讨论的。</p><p>如何重新编程你的大脑。</p><h3 id="_3-身份——你必须成为谁" tabindex="-1">3）身份——你必须成为谁？ <a class="header-anchor" href="#_3-身份——你必须成为谁" aria-label="Permalink to &quot;3）身份——你必须成为谁？&quot;">​</a></h3><p>耶稣会怎么做？</p><p>以前听过这句话吗？</p><p>事实证明，这个问题本身可能就是美好人生的唯一源头。</p><p>我不是基督徒，但我理解这个问题的意义所在。</p><p>耶稣基督，这个人物，象征着一个达到了高阶意识水平的人。在某些圈子里，人们称之为“基督意识”。那时候他们还没有“意识”或“觉知”这样的词，所以我只能想象，如果他们活在今天，他们的信息会被理解得多么清晰。</p><p><img src="'+r+'" alt=""></p><p>我们在<a href="/letters/how-to-join-the-top-1-of-intelligence-full-guide">之前的一篇文章</a>中讨论过这些自我发展的阶段，所以这里我就不再详细解释一遍了。</p><p>相反，我想让你创造一个比你更有意识、更成熟的另我（alter ego），这样你就能采用他们的视角，在那些曾经困难的处境中如鱼得水。</p><p>你的另我，就是<strong>你为了实现愿景、执行计划而必须成为的那个人</strong>。</p><p>正如爱因斯坦据说曾说过的：“你无法用制造问题时的同一层级心智去解决这个问题。”</p><p>所以我们需要接入更高层级的心智，来克服在追求目标过程中遇到的困难，因为你的大多数问题其实不是问题，而是缺乏视角（因而也就是缺乏觉知/意识）。</p><p>下面是我想让你去做的事：</p><p><strong>1）选出2-3个已经实现了你想要实现的目标的理想型原型人物。</strong></p><p>在我打造创业公司的过程中，我常常研究像史蒂夫·乔布斯（Steve Jobs）这样的人物，因为他们的气场是不可否认的。我也直接向像<a href="https://youtu.be/p6n4Q6-N7XI" target="_blank" rel="noreferrer">John Hu 和 Vitalii Dodonov</a> 这样的人学习，他们非常慷慨地帮助我并回答我的问题。</p><p>至于人生意义与灵性方面，你完全可以参考耶稣基督或释迦牟尼佛（Gautama Buddha）。</p><p>互联网美妙的地方在于，你可以直接关注这些人物，读懂他们的心智。</p><p><strong>2）写下你需要采用的品质，以实现你的目标。</strong></p><p>你的任务是研究并理解，究竟是什么品质让这些人如此出众。</p><p>史蒂夫·乔布斯善于表达、富有创造力、能动性极强。佛陀则专注、平静、敏锐。</p><p>这些就是你在需要取得进展时，要“跳入”的那些品质。</p><p><strong>3）给你的另我起一个名字。</strong></p><p>这可以是任何东西。一个人名，一个动物的名字。只要能描述出你想要采纳的那种身份就行。当我在健身房努力刷新纪录时，我会把自己想象成正在变身超级赛亚人的悟空（Goku）。</p><p>创造一个另我，绝不是什么幼稚的把戏。</p><p>它不是那种一摘下来就消失的“面具”。</p><p>它是<strong>身份转变的载体</strong>。</p><p>每当你体现出那些更高层次的品质，并在实现目标的路上取得进展，你的身份就会向更高的技能水平和复杂度扩展。这，简而言之，就是个人<strong>成长</strong>。</p><p>你正在重新编程你的大脑，让它以一种更成熟的视角去感知情境——因为你自己正在变得更加成熟。</p><p>但你不会靠坐在那里说“对，我就是悟空！走，去举铁吧！”就变得更加成熟。</p><p>你要通过承诺、学习、构建和坚持来发展自己。</p><h2 id="如何开启战争模式" tabindex="-1">如何开启战争模式 <a class="header-anchor" href="#如何开启战争模式" aria-label="Permalink to &quot;如何开启战争模式&quot;">​</a></h2><blockquote><p>你还没到达你想去的地方，是因为你还没有把自己置于那些会迫使你到达那里的境地。</p><p><a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》(The Art Of Focus)</a></p></blockquote><p>当你<strong>就是</strong>那个会采取某些行动的人时，你不需要动力或自律。</p><p>要改变你是谁，你必须去学习、练习、体验新的信息，以此重新编程被社会植入你大脑中的错误线路。</p><p>你必须把自己从那个让你一成不变的环境中硬拉出来。</p><p>你必须把自己逼进那些你原本不属于的地方，直到你真正属于那里。</p><p>你必须把学到的东西转化成一个能推动你朝愿景前进的项目。</p><p>带上你的另我，开启战争模式。</p><p>记住，战争模式与僧侣模式不同。</p><p>你去主动攻击你的目标。你模拟一场狩猎。你对一切都说“是”。你让自己暴露在大量的经历之中。你用混乱压倒你的心智，迫使自己扩展成一个新的身份。<strong>你成为那个能够承担巨大责任重担的人。</strong>一个在压力下不会崩溃的人，因为崩溃意味着死亡。</p><h3 id="承诺——剃光你的头" tabindex="-1">承诺——剃光你的头 <a class="header-anchor" href="#承诺——剃光你的头" aria-label="Permalink to &quot;承诺——剃光你的头&quot;">​</a></h3><p>你不必真的剃光头，尤其是如果你是女性。</p><p>但这个道理依然成立：</p><p>去做一件<strong>具体的、身体层面的事</strong>，来代表你<strong>无法回头</strong>的承诺。</p><p>如今社会里太多人只想“试着”改变自己的生活，却不愿承担任何后果。也就不难理解他们很少能取得什么成就。他们留了太多的备用方案。他们没有全力投入自己的愿景，因为他们害怕离开那份舒适——而那份舒适，最终总会证明比投身于你想要的人生更让人不舒服。</p><p>买新衣服。烧掉你的旧衣服。签下一份你负担不起的公寓租约，逼自己让生意运转起来。带着几块钱和一个计划，坐飞机飞到国家的另一头。把你最后的几块钱都投进你事业的营销里。（金钱买不到幸福，但它能买到犯错的能力，而犯错带来成长，成长带来幸福。）</p><p>这是一种战术性的压力。</p><p>去做那件能让你的自我怀疑变得<strong>真实</strong>的事。</p><p>因为此刻，一切都只存在于你的脑子里。而现实往往远没有你想的那么可怕。</p><p>就像一条金鱼一样，你只会长到你被放入的鱼缸那么大。所以把自己放进一个新的鱼缸吧。</p><h3 id="学习——拥抱混乱" tabindex="-1">学习——拥抱混乱 <a class="header-anchor" href="#学习——拥抱混乱" aria-label="Permalink to &quot;学习——拥抱混乱&quot;">​</a></h3><p>你需要两个习惯：</p><ul><li><strong>30-60分钟的学习。</strong> 当世界在快速变化时，你能做的最重要的事就是学习。新技能、新技术、人生中的新路径。花时间去寻找那些可以转化到你工作中的想法。</li><li><strong>30-60分钟的建造。</strong> 如果你想要任何形式的工作、金钱，或维持更好生活的能力，你需要创造出别人真正想要的、有价值的东西。你已经把大部分时间花在为别人建造上，你可以留出一些时间来建造你自己的东西。</li></ul><p>但我们不会止步于此。</p><p>学习远不止读书和看教程那么简单。</p><p>学习是一种人类的基本驱动力。你从日常经历中学习。但你不会在“已知”中学到东西。你不会在过去几年里陷入的那种平庸的日常routine（惯常流程）中学到东西。</p><p>当事情变得静止不变时，你需要改变一些东西。任何东西都行。你需要混乱。你需要新奇。你需要那些能推动你前进的经历和想法。去建造一些新的东西。测试，测试，再测试。把你的日常routine撕开。做任何事，只要不是重复同样的事。</p><h3 id="建造——心智、身体、事业" tabindex="-1">建造——心智、身体、事业 <a class="header-anchor" href="#建造——心智、身体、事业" aria-label="Permalink to &quot;建造——心智、身体、事业&quot;">​</a></h3><p>如果你不知道该建造什么，就从唯一真正重要的东西开始：</p><ul><li><strong>心智</strong>——你如何解读风险与机会，从而做出更好的决策。</li><li><strong>身体</strong>——你的外表、感觉，以及你在他人眼中的样子。</li><li><strong>事业</strong>——你如何为世界贡献价值。</li></ul><p>你与你的心智和身体共存，研究它们、掌控它们、不被它们所支配，理应被视为你的全职工作。</p><p>你的心智和身体让你有能力去改变世界、帮助他人。事业，是把你心智的创造力打包起来，以一种能让你维持理想生活的方式交付给他人的现代方式。你的健康和精力，则是你在不被分心的情况下，把注意力投入到人生事业中的能力。</p><p>你的心智、身体和事业，是唯一会让你的愿景变为现实的优先事项。</p><p>为每一项分别创建一个项目。</p><p>采用一套训练计划。</p><p>启动这项事业。</p><p>在追求这两者的过程中不断获取知识。</p><p>对于那些问“那关系怎么办？”的人，他们不明白的是，通过发展自己，你会顺带改善你的各种关系。你会变得不再那么像个吸血鬼。你的杯子会溢出流向他们的杯子，你也不再需要他们往你的杯子里倒东西。</p><h3 id="让自己暴露在大量的经历之中" tabindex="-1">让自己暴露在大量的经历之中 <a class="header-anchor" href="#让自己暴露在大量的经历之中" aria-label="Permalink to &quot;让自己暴露在大量的经历之中&quot;">​</a></h3><p>战争模式是一段高强度成长的时期。</p><p>它不会永远持续。</p><p>大概2到3个月。</p><p>你能付出的东西是有限的，超过限度你就会精疲力竭。</p><p>所以，倾尽全力去做。</p><p>对一切说“好”。</p><p>去和新的人交谈。接受邀请。启动那个项目。寻求帮助。让你的脑子里塞满混乱，即使你在压力下崩溃，你也会以一个更成熟的人的样子走出来。哪怕飞得太靠近太阳，也要落在月球上。</p><p>我向你保证。</p><p>12个月后回头看，你会完全想不明白自己是怎么走到这么远的。</p><p>经过一段恢复期后，再重来一遍。</p><p>成长不是线性的。</p><p>它是以短暂的指数级爆发的形式出现的进步。</p><p>好在，一旦你练熟了它，你就可以<em>选择</em>去设置正确的变量，来主动催生这样一段成长期。</p><p>我们在另一边见。</p><p>——丹</p><hr><p><a href="/en/letters/how-to-attack-your-big-goals-achieve-them-in-2-3-months">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',213))])}const x=a(c,[["render",d]]);export{T as __pageData,x as default};
